export const invoices = pgTable("invoices", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	user_id: uuid().notNull(),
	project_id: uuid(),
	client_id: uuid(),
	invoice_number: text().notNull(),
	currency: text().$type<Currency>().default('JMD').notNull(),
	subtotal: numeric({ mode: 'number' }).default(0).notNull(),
	gct_rate: numeric({ mode: 'number' }),
	gct_amount: numeric({ mode: 'number' }),
	total: numeric({ mode: 'number' }).default(0).notNull(),
	status: text().$type<InvoiceStatus>().default('draft').notNull(),
	notes: text(),
	due_date: date({ mode: 'string' }),
	discount_type: text().$type<DiscountType>().default('none').notNull(),
	discount_value: numeric({ mode: 'number' }).default(0).notNull(),
	additions_description: text(),
	additions_amount: numeric({ mode: 'number' }).default(0).notNull(),
	amount_paid: numeric({ mode: 'number' }).default(0).notNull(),
	source_meta: jsonb().$type<Record<string, unknown> | null>(),
	created_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow(),
	// Set when created by converting a proposal (see proposals/actions.ts).
	proposal_id: uuid(),
	agreed_amount: numeric({ mode: 'number' }),
	work_started_at: date({ mode: 'string' }),
	// Explicit return type breaks the invoices <-> proposals type-inference cycle.
}, (table): PgTableExtraConfigValue[] => [
	index("idx_invoices_project_id").using("btree", table.project_id.asc().nullsLast().op("uuid_ops")),
	index("idx_invoices_user_id").using("btree", table.user_id.asc().nullsLast().op("uuid_ops")),
	index("invoices_client_id_idx").using("btree", table.client_id.asc().nullsLast().op("uuid_ops")),
	uniqueIndex("invoices_user_number_uniq").using("btree", table.user_id.asc().nullsLast().op("text_ops"), table.invoice_number.asc().nullsLast().op("text_ops")),
	foreignKey({
			columns: [table.client_id],
			foreignColumns: [clients.id],
			name: "invoices_client_id_fkey"
		}).onDelete("set null"),
	foreignKey({
			columns: [table.project_id],
			foreignColumns: [projects.id],
			name: "invoices_project_id_fkey"
		}).onDelete("set null"),
	// proposals is declared below; the callback runs after module init, so this is fine.
	foreignKey({
			columns: [table.proposal_id],
			foreignColumns: [proposals.id],
			name: "invoices_proposal_id_fkey"
		}).onDelete("set null"),
]);

// Money actually received against an invoice — one row per payment. The
// invoice's amount_paid is always the sum of these (lib/payments.ts keeps it
// in sync). receipt_number is RCT-### for payments recorded in the app; NULL
// for the opening rows backfilled from amount_paid before payments were logged.
export const payments = pgTable("payments", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	user_id: uuid().notNull(),
	invoice_id: uuid().notNull(),
	receipt_number: text(),
	amount: numeric({ mode: 'number' }).notNull(),
	paid_on: date({ mode: 'string' }).notNull(),
	method: text().$type<PaymentMethod>(),
	note: text(),
	created_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("payments_invoice_id_idx").using("btree", table.invoice_id.asc().nullsLast().op("uuid_ops")),
	uniqueIndex("payments_user_receipt_uniq").using("btree", table.user_id.asc().nullsLast().op("uuid_ops"), table.receipt_number.asc().nullsLast().op("text_ops")),
	foreignKey({
			columns: [table.invoice_id],
			foreignColumns: [invoices.id],
			name: "payments_invoice_id_fkey"
		}).onDelete("cascade"),
	check("payments_amount_positive", sql`${table.amount} > 0`),
]);

export const invoice_line_items = pgTable("invoice_line_items", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	invoice_id: uuid().notNull(),
	description: text().notNull(),
	quantity: numeric({ mode: 'number' }).default(1).notNull(),
	unit_price: numeric({ mode: 'number' }).default(0).notNull(),
	amount: numeric({ mode: 'number' }).default(0).notNull(),
	sort_order: integer().default(0).notNull(),
	project_id: uuid(),
	section_title: text(),
}, (table) => [
	index("invoice_line_items_project_id_idx").using("btree", table.project_id.asc().nullsLast().op("uuid_ops")),
	foreignKey({
			columns: [table.invoice_id],
			foreignColumns: [invoices.id],
			name: "invoice_line_items_invoice_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.project_id],
			foreignColumns: [projects.id],
			name: "invoice_line_items_project_id_fkey"
		}).onDelete("set null"),
]);

// ---- Proposals (quotes sent before a job becomes a client/project/invoice) ----

export const proposals = pgTable("proposals", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	user_id: uuid().notNull(),
	proposal_number: text().notNull(),
	client_id: uuid(),
	// Always snapshotted (also for existing clients) so a deleted client can't orphan the proposal.
	recipient_name: text().notNull(),
	recipient_phone: text(),
	recipient_email: text(),
	title: text().notNull(),
	scope: text(),
	job_type: text(),
	location_address: text(),
	currency: text().$type<Currency>().default('JMD').notNull(),
	subtotal: numeric({ mode: 'number' }).default(0).notNull(),
	discount_type: text().$type<DiscountType>().default('none').notNull(),
	discount_value: numeric({ mode: 'number' }).default(0).notNull(),
	gct_rate: numeric({ mode: 'number' }).default(0).notNull(),
	gct_amount: numeric({ mode: 'number' }).default(0).notNull(),
	additions_description: text(),
	additions_amount: numeric({ mode: 'number' }).default(0).notNull(),
	total: numeric({ mode: 'number' }).default(0).notNull(),
	notes: text(),
	valid_until: date({ mode: 'string' }).notNull(),
	status: text().$type<StoredProposalStatus>().default('draft').notNull(),
	share_token: uuid().defaultRandom().notNull(),
	changes_requested_at: timestamp({ withTimezone: true, mode: 'string' }),
	accepted_at: timestamp({ withTimezone: true, mode: 'string' }),
	accepted_version: integer(),
	accepted_by_name: text(),
	converted_at: timestamp({ withTimezone: true, mode: 'string' }),
	invoice_id: uuid(),
	project_id: uuid(),
	created_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updated_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	uniqueIndex("proposals_user_number_uniq").using("btree", table.user_id.asc().nullsLast().op("uuid_ops"), table.proposal_number.asc().nullsLast().op("text_ops")),
	unique("proposals_share_token_key").on(table.share_token),
	index("proposals_user_id_idx").using("btree", table.user_id.asc().nullsLast().op("uuid_ops")),
	check("proposals_status_check", sql`${table.status} in ('draft','sent','revised','accepted','declined','converted')`),
	foreignKey({
			columns: [table.client_id],
			foreignColumns: [clients.id],
			name: "proposals_client_id_fkey"
		}).onDelete("set null"),
	foreignKey({
			columns: [table.invoice_id],
			foreignColumns: [invoices.id],
			name: "proposals_invoice_id_fkey"
		}).onDelete("set null"),
	foreignKey({
			columns: [table.project_id],
			foreignColumns: [projects.id],
			name: "proposals_project_id_fkey"
		}).onDelete("set null"),
]);

export const proposal_line_items = pgTable("proposal_line_items", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	proposal_id: uuid().notNull(),
	category: text().$type<ProposalItemCategory>(),
	description: text().notNull(),
	quantity: numeric({ mode: 'number' }).default(1).notNull(),
	unit_price: numeric({ mode: 'number' }).default(0).notNull(),
	amount: numeric({ mode: 'number' }).default(0).notNull(),
	sort_order: integer().default(0).notNull(),
}, (table) => [
	index("proposal_line_items_proposal_id_idx").using("btree", table.proposal_id.asc().nullsLast().op("uuid_ops")),
	foreignKey({
			columns: [table.proposal_id],
			foreignColumns: [proposals.id],
			name: "proposal_line_items_proposal_id_fkey"
		}).onDelete("cascade"),
]);

export const proposal_versions = pgTable("proposal_versions", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	proposal_id: uuid().notNull(),
	version: integer().notNull(),
	snapshot: jsonb().$type<ProposalSnapshot>().notNull(),
	total: numeric({ mode: 'number' }).notNull(),
	sent_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	uniqueIndex("proposal_versions_proposal_version_uniq").using("btree", table.proposal_id.asc().nullsLast().op("uuid_ops"), table.version.asc().nullsLast().op("int4_ops")),
	foreignKey({
			columns: [table.proposal_id],
			foreignColumns: [proposals.id],
			name: "proposal_versions_proposal_id_fkey"
		}).onDelete("cascade"),
]);

export const proposal_responses = pgTable("proposal_responses", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	proposal_id: uuid().notNull(),
	version: integer().notNull(),
	kind: text().$type<'accept' | 'changes'>().notNull(),
	responder_name: text(),
	note: text(),
	// Salted SHA-256 of the client IP (rate limiting only; the raw IP is never stored).
	ip_hash: text(),
	created_at: timestamp({ withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("proposal_responses_proposal_created_idx").using("btree", table.proposal_id.asc().nullsLast().op("uuid_ops"), table.created_at.asc().nullsLast().op("timestamptz_ops")),
	index("proposal_responses_ip_created_idx").using("btree", table.ip_hash.asc().nullsLast().op("text_ops"), table.created_at.asc().nullsLast().op("timestamptz_ops")),
	check("proposal_responses_kind_check", sql`${table.kind} in ('accept','changes')`),
	foreignKey({
			columns: [table.proposal_id],
			foreignColumns: [proposals.id],
			name: "proposal_responses_proposal_id_fkey"
		}).onDelete("cascade"),
]);

